"""本地业务页面交互。"""

def detail_fragment(item):
    return "<select id=\"category\"><option>手作</option><option>食饮</option></select><input id=\"attachment\" type=\"file\"><button id=\"draft\">保存演练草稿</button><output id=\"draft-state\"></output><button id=\"confirm\">查看确认页</button><output id=\"confirmation\"></output><script>let category=document.querySelector('#category'),attachment=document.querySelector('#attachment'),status=document.querySelector('#draft-state'),confirm=document.querySelector('#confirmation');let version=0;category.onchange=()=>{version++;attachment.value='';status.textContent='材料待核对';confirm.textContent=''};attachment.onchange=()=>{version++;status.textContent=attachment.files.length?'已预览：'+attachment.files[0].name:'材料待核对';confirm.textContent=''};document.querySelector('#draft').onclick=()=>{sessionStorage.setItem('stall-draft',JSON.stringify({category:category.value,filename:attachment.files[0]?.name||null,version}));status.textContent='草稿：'+category.value+' / v'+version};document.querySelector('#confirm').onclick=()=>{let draft=JSON.parse(sessionStorage.getItem('stall-draft')||'null');confirm.textContent=draft?.version===version?'待人工确认 / v'+version:'草稿已变化'};</script>"
